import {SIZE,dimensions,equippedColor,COSMETICS} from './engine.js';
export const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const project=(x,y,z=0)=>[500+(x-y)*44,250+(x+y)*22-z];
export const unproject=(x,y)=>{const a=(x-500)/44,b=(y-250)/22;return [(a+b)/2,(b-a)/2];};
const pt=a=>a.map(v=>v.toFixed(2)).join(',');
const poly=(pts,fill,attrs='')=>`<polygon points="${pts.map(pt).join(' ')}" fill="${fill}" ${attrs}/>`;
const line=(a,b,color,width=1)=>`<path d="M${pt(a)}L${pt(b)}" fill="none" stroke="${color}" stroke-width="${width}"/>`;
export function icon(name,size=22){const paths={suite:'M3 10 12 3l9 7v11h-7v-7h-4v7H3Z',hotel:'M4 21V5h16v16M9 21v-4h6v4M8 9h1m6 0h1M8 13h1m6 0h1',avatar:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',rewards:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',chat:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4ZM8 10h8m-8 4h5',edit:'m4 16-1 5 5-1L20 8l-4-4ZM14 6l4 4',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-5-5 5 5-5 5',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',coin:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v10m3-8H10a2 2 0 0 0 0 4h4a2 2 0 0 1 0 4H9',plus:'M12 5v14M5 12h14',minus:'M5 12h14',sound:'M4 9v6h4l5 4V5L8 9Zm13-2a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16',mute:'M4 9v6h4l5 4V5L8 9Zm13 1 5 5m-5 0 5-5',check:'m5 12 4 4L20 5',rotate:'M4 9a8 8 0 1 1 1 10M4 3v6h6',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',lock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4',info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',fit:'M3 9V3h6m6 0h6v6M3 15v6h6m6 0h6v-6',door:'M5 21V3h11v18Zm5-9h1m7-3 4 3-4 3m-3-3h7',star:'m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3L12 17.4l-5.6 3 1.1-6.3L3 9.6l6.2-.9Z'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;}
function local(x,y,z=0){return [(x-y)*44,(x+y)*22-z];}
function cube(x,y,w,d,h,top='#d5bd8b',left='#9d805b',right='#b29568',z=0){const p=(a,b,c)=>local(a,b,c);return poly([p(x,y,z),p(x,y+d,z),p(x,y+d,z+h),p(x,y,z+h)],left)+poly([p(x+w,y,z),p(x+w,y+d,z),p(x+w,y+d,z+h),p(x+w,y,z+h)],right)+poly([p(x,y+d,z),p(x+w,y+d,z),p(x+w,y+d,z+h),p(x,y+d,z+h)],right)+poly([p(x,y,z+h),p(x+w,y,z+h),p(x+w,y+d,z+h),p(x,y+d,z+h)],top,'stroke="#0d1e2420" stroke-width=".7"');}
const ellipse=(cx,cy,rx,ry,fill,attrs='')=>`<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${fill}" ${attrs}/>`;
export function objectArt(obj,game='gold'){
 const [w,d]=dimensions(obj),type=obj.type;let s='';
 if(type==='sofa'||type==='chair'){const ww=type==='chair'?1:w,dd=type==='chair'?1:d;const teal=type==='chair'?['#b48565','#815c49','#a17154']:['#438b7e','#235b55','#337568'];
 s+=cube(.13,.16,ww-.24,dd-.24,7,'#bf9e65','#80683f','#9f814e');s+=cube(.06,.06,ww-.12,dd-.12,21,...teal,8);s+=cube(.04,.02,ww-.08,.22,39,...teal,8);s+=cube(.02,.13,.21,dd-.17,30,...teal,8);s+=cube(ww-.23,.13,.21,dd-.17,30,...teal,8);
 for(let i=0;i<(ww>1?2:1);i++)s+=cube(.28+i*(ww-.55)/2,.3,(ww-.6)/(ww>1?2:1),dd-.41,6,'#60a294','#327b70','#4c9587',27);
 s+=cube(.35,.3,.27,.27,8,'#d3b885','#aa8e63','#bea474',36);
 }else if(type==='table'){s+=cube(.43,.4,.15,.15,27,'#bb9d5f','#8d7046','#b1955f');s+=cube(.05,.05,.9,.9,7,'#e8dfc7','#a69d8d','#c4bca7',27);s+=line(local(.08,.3,34),local(.7,.85,34),'#b8b2a1',1);const p=local(.65,.35,34);s+=ellipse(p[0],p[1],6,3,'#b98e55')+`<path d="M${p[0]-4},${p[1]-8}h8v8h-8Z" fill="#ebe3d0"/>`;
 }else if(type==='plant'){s+=cube(.28,.28,.44,.44,23,'#d9c9a4','#ac997b','#c2b18d');const [x,y]=local(.5,.5,23);s+=`<path d="M${x} ${y+2}q-3-34 2-57" stroke="#566b43" stroke-width="4" fill="none"/>`;for(let i=0;i<8;i++){const angle=i*2.5,xx=x+Math.sin(angle)*29,yy=y-35+Math.cos(angle)*22;s+=`<path d="M${x},${y-15}Q${xx-8},${yy-36} ${xx},${yy}Q${xx+8},${yy-3} ${x},${y-15}" fill="${['#54865d','#36694c','#67966a','#447955'][i%4]}"/>`;}
 }else if(type==='lamp'){const [x,y]=local(.5,.5);s+=ellipse(x,y,14,7,'#a58d58')+`<path d="M${x} ${y-3}v-75" stroke="#d2b67a" stroke-width="4"/>`+ellipse(x,y-88,19,7,'#f7e4b5')+`<path d="M${x-19} ${y-88}l-6 24q25 14 50 0l-6-24" fill="#ead8ae"/>`+ellipse(x,y-64,25,8,'#c8b98e')+ellipse(x,y-65,20,5,'#ffedb1')+ellipse(x,y-51,39,24,'url(#warmGlow)');
 }else if(type==='shelf'){s+=cube(0,0,w,d,58,'#ad8b5f','#604d3d','#80654a');s+=cube(.05,d-.035,w-.1,.05,39,'#a98b61','#503e32','#4b4036',9);for(let i=0;i<(w>1?10:5);i++){const xx=.15+i*(w-.25)/(w>1?10:5);s+=cube(xx,d-.08,.1,.11,16+(i%3)*5,['#b76e5d','#7c9c8a','#d2b37b','#8b8a9d'][i%4],'#302c2b',['#b76e5d','#7c9c8a','#d2b37b','#8b8a9d'][i%4],13);}s+=cube(.12,.2,.55,.4,5,'#242e31','#101d21','#303a3d',59);const p=local(.4,.4,65);s+=ellipse(...p,13,6,'#151d20')+ellipse(...p,4,2,'#c8aa71');
 }else if(type==='bed'){s+=cube(.02,.02,1.96,1.96,19,'#b69462','#806544','#9b7b50');s+=cube(.02,.02,1.96,.16,61,'#8aa19a','#516e64','#66887d',16);s+=cube(.1,.16,1.8,1.7,17,'#e9e2d1','#b8b1a0','#d4ccba',19);s+=cube(.1,.92,1.8,.94,6,'#bd8866','#815e4a','#a77758',37);s+=cube(.15,.18,.74,.46,10,'#f5efde','#c5beac','#ddd5c2',37);s+=cube(1.02,.18,.74,.46,10,'#f5efde','#c5beac','#ddd5c2',37);for(let i=0;i<6;i++)s+=line(local(.18+i*.3,1,44),local(.18+i*.3,1.8,44),'#cda180',1);
 }else if(type==='machine'){const neon=(obj.game||game)==='neon',c=neon?['#8b83e6','#342d63','#524b8e']:['#cbaa64','#53462d','#8e733d'];s+=cube(.17,.1,.68,.66,10,...c);s+=cube(.2,.12,.6,.54,44,...c,10);s+=cube(.13,.07,.74,.5,51,...c,51);s+=cube(.1,.06,.8,.55,7,...c,102);const [x,y]=local(.2,.58,57);s+=`<path d="M${x},${y}l27 13v-38l-27-13Z" fill="${neon?'#242147':'#182e31'}" stroke="${neon?'#b6a5ff':'#e2c27a'}" stroke-width="2"/>`;
 for(let i=0;i<3;i++)s+=`<path d="M${x+4+i*8} ${y-31+i*4}l6 3v18l-6-3Z" fill="${neon?'#a6e5e1':'#e8d9b5'}"/><path d="M${x+5+i*8} ${y-25+i*4}l4 2v7l-4-2Z" fill="${neon?'#a06be7':'#a55646'}"/>`;
 s+=cube(.1,.55,.8,.28,5,...c,53);const b=local(.5,.7,60);s+=ellipse(...b,5,2.5,neon?'#9dffff':'#df6b54');s+=`<path d="M${x+31} ${y-12}v-20" stroke="#b9a374" stroke-width="3"/><circle cx="${x+31}" cy="${y-32}" r="4" fill="${neon?'#80dfec':'#bd5f4d'}"/>`;
 const title=local(.52,.2,114);s+=`<text x="${title[0]}" y="${title[1]}" font-family="Georgia" font-size="8" font-weight="bold" text-anchor="middle" fill="${neon?'#c2faff':'#f4dfac'}">${neon?'NOVA':'GRAND 7'}</text>`;
 s+=ellipse(0,32,35,18,neon?'#9e8bff14':'#e4bb6012');
 }else if(type==='bar'){s+=cube(.05,.05,2.9,.9,55,'#dfcda9','#546d61','#6c887a');s+=cube(0,0,3,1,6,'#e1d6bb','#b6a78a','#d1c3a5',55);for(let i=0;i<3;i++){s+=cube(.45+i*.8,.3,.12,.12,15,['#48735b','#a56d4e','#777ba1'][i],'#385546','#6f9272',61);}const p=local(1.5,.92,32);s+=`<text x="${p[0]}" y="${p[1]}" text-anchor="middle" fill="#d9bd7c" font-family="Georgia" font-size="15">G</text>`;
 }else if(type==='sign'){s+=cube(.15,.3,.7,.35,6,'#c8af76','#9b834f','#b29a64');s+=cube(.44,.42,.1,.1,62,'#cfb67c','#ad945d','#c5a96a');const [x,y]=local(.5,.45,65);s+=`<rect x="${x-27}" y="${y-41}" width="54" height="37" rx="4" fill="#163b38" stroke="#c4aa71" stroke-width="2"/><text x="${x}" y="${y-26}" text-anchor="middle" font-size="8" fill="#dfc68b">DIRECTORY</text><path d="M${x-12} ${y-15}h24m-5-4 5 4-5 4" stroke="#d6bb82" fill="none"/>`;
 }else if(type==='speaker'){s+=cube(.1,.1,.8,.8,72,'#55516b','#262d3e','#3d4054');const p=local(.5,.91,40);s+=ellipse(p[0],p[1],13,19,'#1f2836')+ellipse(p[0],p[1],7,11,'#6b6589')+ellipse(p[0],p[1]-28,6,7,'#aea6d0');
 }else{s+=cube(.3,.3,.4,.4,32,'#d9c496','#b39b62','#ccb37c');const p=local(.5,.5,56);s+=`<path d="M${p[0]},${p[1]-26}l19 28-19 17-19-17Z" fill="#d4b56c" stroke="#f1d599"/>`;}
 return `<g class="object-art">${s}</g>`;
}
function wallWindow(side,start,width){const p=(u,z)=>side==='left'?project(0,u,z):project(u,0,z);let s=poly([p(start,55),p(start+width,55),p(start+width,164),p(start,164)],'#bda978','stroke="#173b3c" stroke-width="8"');s+=poly([p(start+.08,60),p(start+width-.08,60),p(start+width-.08,158),p(start+.08,158)],'url(#nightSky)');for(let i=0;i<6;i++){const a=start+.12+i*width/7,ht=15+(i%3)*13;s+=poly([p(a,60),p(a+.12,60),p(a+.12,60+ht),p(a,60+ht)],'#243a4c');}s+=line(p(start+width/2,59),p(start+width/2,163),'#b9a16d',3)+line(p(start,107),p(start+width,107),'#b9a16d',2);s+=poly([p(start-.08,51),p(start+width+.08,51),p(start+width+.08,57),p(start-.08,57)],'#d3c098');return s;}
export function roomArt(room,state){let s=`<defs><linearGradient id="nightSky" x2="0" y2="1"><stop stop-color="#122f41"/><stop offset="1" stop-color="#547a87"/></linearGradient><radialGradient id="warmGlow"><stop stop-color="#ffe6a7" stop-opacity=".2"/><stop offset="1" stop-color="#ffe6a7" stop-opacity="0"/></radialGradient><filter id="shadow" x="-60%" y="-100%" width="220%" height="300%"><feGaussianBlur stdDeviation="15"/></filter></defs>`;
 const theme=state.theme==='rose'?'#805d63':state.theme==='midnight'?'#40516c':room.wall;
 if(room.short==='Rooftop Club'){for(let i=0;i<30;i++){const x=90+i*29,h=40+(i*37)%130;s+=`<rect x="${x}" y="${250-h}" width="22" height="${h+150}" rx="2" fill="#253c4f" opacity=".5"/>`;for(let j=0;j<4;j++)s+=`<rect x="${x+4+(j%2)*10}" y="${258-h+Math.floor(j/2)*19}" width="3" height="5" fill="#d4b58a" opacity=".5"/>`;}}
 s+=ellipse(500,568,345,134,'#060f1680','filter="url(#shadow)"');
 const p=project;const wallH=room.short==='Rooftop Club'?56:178;
 s+=poly([p(0,0),p(0,8),p(0,8,wallH),p(0,0,wallH)],theme)+poly([p(0,0),p(8,0),p(8,0,wallH),p(0,0,wallH)],room.short==='My Suite'?theme:room.wall);
 s+=poly([p(0,0,wallH),p(0,8,wallH),p(-.15,8,wallH+6),p(-.15,-.15,wallH+6),p(8,-.15,wallH+6),p(8,0,wallH)],'#c1ac7c');
 for(const z of [12,38,wallH-14])s+=line(p(0,8,z),p(0,0,z),'#c6ae7655',z===12?5:1.5)+line(p(0,0,z),p(8,0,z),'#c6ae7655',z===12?5:1.5);
 if(room.short!=='Rooftop Club'){
 for(let i=0;i<8;i++)s+=line(p(0,i+.08,42),p(0,i+.08,wallH-18),'#d4c28b20')+line(p(i+.08,0,42),p(i+.08,0,wallH-18),'#d4c28b20');
 s+=wallWindow('left',.8,1.7)+wallWindow('left',4.5,1.7)+wallWindow('right',1.1,2.2);
 // Original geometric art in a brass frame.
 s+=poly([p(4.4,0,64),p(5.8,0,64),p(5.8,0,148),p(4.4,0,148)],'#d1b67b','stroke="#244d48" stroke-width="5"');s+=poly([p(4.5,0,70),p(5.7,0,70),p(5.7,0,142),p(4.5,0,142)],'#e1c49a');s+=poly([p(4.55,0,72),p(5.65,0,72),p(5.1,0,132)],'#588176')+poly([p(4.65,0,72),p(5.65,0,72),p(5.65,0,117)],'#ae735d');
 }else{const a=p(0,8,125),b=p(0,0,150),c=p(8,0,125);s+=`<path d="M${pt(a)}Q310,220 ${pt(b)}Q700,215 ${pt(c)}" fill="none" stroke="#918875" stroke-width="2"/>`;for(let i=0;i<=16;i++){const u=i/16,x=148+u*704,y=120+Math.abs(u-.5)*100;s+=ellipse(x,y,5,7,'#ffe5ac')+ellipse(x,y,16,20,'url(#warmGlow)');}}
 // The raised floor is a solid object, not a floating diamond.
 s+=poly([p(0,8),p(8,8),p(8,8,-16),p(0,8,-16)],'#6d6659')+poly([p(8,0),p(8,8),p(8,8,-16),p(8,0,-16)],'#8a7d67');
 for(let x=0;x<SIZE;x++)for(let y=0;y<SIZE;y++){const isSuite=room.short==='My Suite',a=isSuite&&state.floor==='stone'?'#b4b9ad':room.floorA,b=isSuite&&state.floor==='stone'?'#a9afa5':room.floorB;let col=(x+y)%2?a:b;s+=poly([p(x,y),p(x+1,y),p(x+1,y+1),p(x,y+1)],col,`data-tile="${x},${y}" stroke="#5b55412d" stroke-width=".8"`);if(isSuite&&state.floor!=='stone'){for(let j=1;j<=3;j++)s+=line(p(x+j/4,y),p(x+j/4,y+1),'#7357362a',.7);s+=line(p(x+.25,y+.5),p(x+.5,y+.5),'#7357362a',.6);}else if(!isSuite)s+=poly([p(x+.42,y+.42),p(x+.58,y+.42),p(x+.58,y+.58),p(x+.42,y+.58)],'#dbc58e80');}
 s+=poly([p(2,2),p(5.5,2),p(5.5,5.5),p(2,5.5)],room.rug,'stroke="#ddc08b" stroke-width="1.3" opacity=".93" pointer-events="none"')+poly([p(2.16,2.16),p(5.34,2.16),p(5.34,5.34),p(2.16,5.34)],'none','stroke="#c9b57e80" stroke-width="1" pointer-events="none"');
 const cc=p(3.75,3.75);s+=`<g transform="translate(${cc})" opacity=".22" pointer-events="none"><path d="M0-48 55 0 0 48-55 0Z M0-32 37 0 0 32-37 0Z" fill="none" stroke="#edd09a" stroke-width="2"/><text y="8" text-anchor="middle" font-family="Georgia" font-size="25" fill="#ead09c">G</text></g>`;
 const ex=p(7.5,7.5);s+=`<g data-exit="true" tabindex="0" role="button" aria-label="Open hotel directory"><path d="M${ex[0]-35} ${ex[1]}l35-17 35 17-35 17Z" fill="#1b4e48" stroke="#c3ad76" stroke-width="2"/><path d="M${ex[0]-8} ${ex[1]-3}h16m-4-4 4 4-4 4" stroke="#e8c98d" stroke-width="2" fill="none"/><rect x="${ex[0]-43}" y="${ex[1]+23}" width="86" height="21" rx="10" fill="#142b30"/><text x="${ex[0]}" y="${ex[1]+37}" text-anchor="middle" fill="#e6d6b0" font-size="10" letter-spacing="1.4">${room.short==='My Suite'?'TO HOTEL':'DIRECTORY'}</text></g>`;
 return s;
}
export function avatarArt(state,npc=false){const body=npc?state.body:equippedColor(state),hair=npc?state.hair:(COSMETICS.hair.find(c=>c.id===state.hair)?.color||'#3b302d'),skin=state.skin||'#d6a080';return `
 <ellipse cx="0" cy="0" rx="17" ry="7" fill="#10282b36"/>
 <g class="figure"><g class="leg leg-left"><path d="M-10-22h9l-1 21h-9Z" fill="#38414b"/><path d="M-12-5h11v7h-15v-4Z" fill="#222e36"/></g><g class="leg leg-right"><path d="M2-22h9L13-1H3Z" fill="#303b45"/><path d="M3-4h11l3 5H3Z" fill="#1b2830"/></g>
 <path d="M-12-49q12-6 24 0l3 27q-13 9-30 0Z" fill="${body}"/><path d="M-12-47-18-39l2 17 6 1 1-23M12-47l7 10-1 14-6 2-2-23" fill="${body}"/><path d="M-16-23v5q4 4 7-1l-1-5M12-23l-1 6q6 3 8-2v-5" fill="${skin}"/>
 <path d="M-3-49 1-38 5-50" fill="#f0dfbe" opacity=".9"/><path d="M1-39v17" stroke="#ffffff1f"/>
 <rect x="-6" y="-58" width="12" height="12" rx="4" fill="${skin}"/><path d="M-13-76q13-12 26 0l-1 19q-11 13-23 0Z" fill="${skin}"/><path d="M-14-66v-12q5-14 21-9l9 8-1 17-5-12q-13 5-20 0l-2 12Z" fill="${hair}"/><path d="M-14-76q8-17 26-7l5 7q-14-6-31 5Z" fill="${hair}"/>
 <path d="M-6-64h2m9 0h2" stroke="#44362f" stroke-width="2.4" stroke-linecap="round"/><path d="M-2-55q4 3 7-1" stroke="#986249" fill="none" stroke-width="1.5"/>
 ${state.hat==='beanie'?'<path d="M-15-78q0-20 15-20t16 20" fill="#be8a5e"/><rect x="-16" y="-82" width="33" height="9" rx="3" fill="#dcad7d"/><rect x="-2" y="-82" width="6" height="6" rx="1" fill="#eadac1"/>':''}
 ${state.hat==='fedora'?'<path d="m-12-85 3-14 11 3 10-3 4 17Z" fill="#8a5260"/><ellipse cx="1" cy="-82" rx="24" ry="5" fill="#a76b77"/><path d="M-11-86h25" stroke="#d1af77" stroke-width="3"/>':''}
 ${state.accessory==='glasses'?'<g fill="none" stroke="#393b38" stroke-width="2"><circle cx="-5" cy="-64" r="5"/><circle cx="7" cy="-64" r="5"/><path d="M0-65h2"/></g>':''}
 ${state.accessory==='pin'?'<path d="m8-43 4 5-4 5-4-5Z" fill="#edce7d"/>':''}</g>`;}
export function avatarSvg(state){return `<svg viewBox="-75 -125 150 150" role="img" aria-label="Your avatar">${avatarArt(state)}</svg>`;}
export function objectSvg(obj,game){return `<svg viewBox="-80 -110 180 200" aria-hidden="true">${objectArt(obj,game)}</svg>`;}
export function symbolSvg(symbol){const shapes={seven:'<text x="50" y="76" font-family="Georgia" font-size="79" font-weight="bold" text-anchor="middle" fill="#b85f52">7</text>',diamond:'<path d="M50 16 82 45 50 84 18 45Z" fill="#6fa5a5" stroke="#b8e0cd" stroke-width="3"/><path d="m18 45 32 5 32-5M50 16v68" fill="none" stroke="#d9edda" stroke-width="2"/>',crown:'<path d="m18 32 17 17 15-25 15 25 17-17-8 39H26Z" fill="#d5b260" stroke="#f4d991" stroke-width="3"/><path d="M27 78h46" stroke="#c69847" stroke-width="6"/>',cherry:'<path d="M37 52q-1-25 26-32 7 15 3 34" stroke="#54876a" stroke-width="5" fill="none"/><circle cx="33" cy="65" r="17" fill="#b35b60"/><circle cx="65" cy="67" r="17" fill="#ce7775"/><path d="M56 24q17-17 27-5-9 13-27 5" fill="#679176"/>',orb:'<circle cx="50" cy="50" r="28" fill="#7971bf" stroke="#a5ece0" stroke-width="4"/><ellipse cx="50" cy="50" rx="40" ry="12" fill="none" stroke="#b5b0ff" stroke-width="5" transform="rotate(-25 50 50)"/>',bolt:'<path d="m56 10-33 48h24l-6 33 36-51H53Z" fill="#bcabef" stroke="#e7d9ff" stroke-width="3"/>',star:'<path d="m50 12 11 26 29 3-22 19 7 28-25-15-25 15 7-28L10 41l29-3Z" fill="#d5b260" stroke="#fae9a3" stroke-width="3"/>'};return `<svg viewBox="0 0 100 100" aria-label="${esc(symbol)}">${shapes[symbol]||shapes.star}</svg>`;}
